// SmartLibrary fictional demonstration data
(() => {
    const books = [{"id":"B001","title":"THE SYSTEM","author":"James Ball","isbn":"DEMO-001","category":"Information Systems","location":"A-01","quantity":5,"available":5,"cover":"data:image/jpeg;base64,"},{"id":"B002","title":"ATOMIC HABITS","author":"James Clear","isbn":"DEMO-002","category":"Database","location":"A-02","quantity":4,"available":4,"cover":"data:image/jpeg;base64,"},{"id":"B003","title":"THE PSYCHOLOGY OF MONEY","author":"Morgan Housel","isbn":"DEMO-003","category":"Project Management","location":"B-01","quantity":6,"available":6,"cover":"data:image/jpeg;base64,"},{"id":"B004","title":"MAKERS AND TAKERS","author":"Rana Foroohar","isbn":"DEMO-004","category":"Research","location":"B-02","quantity":5,"available":5,"cover":"data:image/jpeg;base64,"},{"id":"B005","title":"Introduction to Information Science","author":"David Bawden & Lyn Robinson","isbn":"DEMO-005","category":"Information Science","location":"C-01","quantity":4,"available":4,"cover":"data:image/jpeg;base64,"},{"id":"B006","title":"Data Science for Business","author":"Foster Provost & Tom Fawcett","isbn":"DEMO-006","category":"Data Analytics","location":"C-02","quantity":6,"available":6,"cover":"data:image/jpeg;base64,"},{"id":"B1795154417496","title":"1984","author":"George Orwell","isbn":"DEMO-007","category":"Research","location":"C-07","quantity":3,"available":3,"cover":"data:image/jpeg;base64,"},{"id":"B1795154486349","title":"A BRIEF HISTORY OF TIME","author":"Stephen Hawking","isbn":"DEMO-008","category":"Research","location":"D-08","quantity":4,"available":4,"cover":"data:image/jpeg;base64,"},{"id":"B1795154542291","title":"THE LET THEM THEORY","author":"Mel Robbins","isbn":"DEMO-009","category":"Database","location":"A-09","quantity":4,"available":4,"cover":"data:image/jpeg;base64,"},{"id":"B1795154625139","title":"SURROUNDED BY IDIOTS","author":"Thomas Erikson","isbn":"DEMO-010","category":"Data Analytics","location":"A-010","quantity":5,"available":5,"cover":"data:image/jpeg;base64,"},{"id":"B1795154692829","title":"THINKING, FAST AND SLOW","author":"Daniel Kehneman","isbn":"DEMO-011","category":"Research","location":"D-011","quantity":3,"available":3,"cover":"data:image/jpeg;base64,"},{"id":"B1795154792413","title":"T-MINUS AI","author":"Michael Kanaan","isbn":"DEMO-012","category":"Information Systems","location":"E-12","quantity":3,"available":3,"cover":"data:image/jpeg;base64,"},{"id":"B1795154888365","title":"THE INNOVATORS","author":"Walter Isaacson & Steve Jobs","isbn":"DEMO-013","category":"Data Analytics","location":"E-013","quantity":2,"available":2,"cover":"data:image/jpeg;base64,"},{"id":"B1795154993321","title":"DATABASE SYSTEMS","author":"Coronel / Morris / Rob","isbn":"DEMO-014","category":"Database","location":"B-014","quantity":6,"available":6,"cover":"data:image/jpeg;base64,"},{"id":"B1795155041900","title":"DATABASE INTERNALS","author":"Alex Petrov","isbn":"DEMO-015","category":"Database","location":"E-15","quantity":1,"available":1,"cover":"data:image/jpeg;base64,"},{"id":"B1795155110498","title":"FROM TRANSISTOR TO BROWSER","author":"Alex Sarkar","isbn":"DEMO-016","category":"Information Science","location":"A-07","quantity":4,"available":4,"cover":"data:image/jpeg;base64,"}];
    const read = key => JSON.parse(localStorage.getItem(key) || "[]");
    const students = read("students");
    const demo = {name:"Demo Student",studentId:"2026123456",email:"student@example.com",faculty:"Faculty of Information Science",programme:"Information Systems",password:"123456"};
    if (!students.some(s => s.studentId === demo.studentId)) {
        students.push(demo);
        localStorage.setItem("students", JSON.stringify(students));
    }
    if (localStorage.getItem("smartLibraryDemoV1")) return;
    // Preserve existing borrowing and payment records.
    if (read("transactions").length || read("payments").length) return;
    const existing = read("books");
    const catalogue = existing.length ? existing : books;
    if (catalogue.some(b => b.available !== b.quantity)) return;
    const date = (offset, base = new Date()) => {
        const d = new Date(base); d.setDate(d.getDate() + offset);
        return d.getFullYear() + "-" + String(d.getMonth()+1).padStart(2,"0") + "-" + String(d.getDate()).padStart(2,"0");
    };
    const transactions = [], payments = [];
    function add(book, offset, returned, late = 0, paid = false) {
        const id = "DEMO-T" + String(transactions.length+1).padStart(3,"0");
        const fine = returned ? late * 0.5 : 0;
        const t = {id,studentId:demo.studentId,studentName:demo.name,bookId:book.id,bookTitle:book.title,borrowDate:date(offset),dueDate:date(offset+14),returnDate:returned?date(offset+10+(late?4+late:0)):"",status:returned?"Returned":"Borrowed",fine,paidAmount:paid?fine:0};
        transactions.push(t);
        if (!returned) book.available--;
        if (paid) payments.push({id:"DEMO-P"+payments.length,transactionId:id,studentId:demo.studentId,bookTitle:book.title,amount:fine,method:["Cash","Bank Transfer","QR Payment"][payments.length%3],paymentDate:t.returnDate});
    }
    for(let i=0;i<42;i++) add(catalogue[i%catalogue.length],-35-i*4,true,i<12?2+i%5:0,i<8);
    catalogue.slice(0,Math.min(16,catalogue.length)).forEach((book,i)=>{if(book.available>0)add(book,i<5?-20-i:-2-i%7,false);});
    localStorage.setItem("books",JSON.stringify(catalogue));
    localStorage.setItem("transactions",JSON.stringify(transactions));
    localStorage.setItem("payments",JSON.stringify(payments));
    localStorage.setItem("sampleBooksLoaded","true");
    localStorage.setItem("smartLibraryDemoV1","true");
})();
